class CircleShape {                       // Abstraction
  #renderer
  constructor(renderer, radius) {
    this.#renderer = renderer             // injected, never constructed here
    this.radius = radius
  }
  draw() { this.#renderer.circle(this.radius) }
}

const cairo = { circle: (r) => drawArc(0, 0, r) }   // duck-typed Implementor
